package android.app;import java.util.*;import android.os.Bundle;public class Application {public List<ActivityLifecycleCallbacks> callbacks=new ArrayList<>();public void registerActivityLifecycleCallbacks(ActivityLifecycleCallbacks c){callbacks.add(c);}public void unregisterActivityLifecycleCallbacks(ActivityLifecycleCallbacks c){callbacks.remove(c);}public interface ActivityLifecycleCallbacks {void onActivityStopped(Activity a);void onActivityDestroyed(Activity a);void onActivityCreated(Activity a,Bundle b);void onActivityStarted(Activity a);void onActivityResumed(Activity a);void onActivityPaused(Activity a);void onActivitySaveInstanceState(Activity a,Bundle b);}}
